        errorTypes.some(type => r.reason instanceof type),
        `unexpected rejection: ${r.reason && r.reason.stack}`
      );
    }
  }
}

// Recomputes each SKU's counters from the order records and checks they match
// the SKU record: reserved is what open orders hold, sold is what committed
// orders took, and available never goes negative.
async function assertLedger(svc, received) {
  const orders = await Promise.all((await svc.store.keys('order:')).map(key => svc.store.get(key)));
  for (const [sku, stock] of Object.entries(received)) {
    let reserved = 0;
    let sold = 0;
    for (const order of orders) {
      for (const line of order.items) {
        if (line.sku !== sku) continue;
        if (order.status === 'reserved') reserved += line.qty;
        if (order.status === 'committed') sold += line.qty;
      }
    }
    assert.deepEqual(await svc.snapshot(sku), { sku, stock: stock - sold, reserved, sold }, `ledger for ${sku}`);
    assert.ok(stock - sold - reserved >= 0, `available for ${sku} went negative`);
  }
}

describe('INC-5521: oversold stock', () => {
  test('263 concurrent orders for 250 units confirm exactly 250', async () => {
    const svc = await service({ 'sneaker-limited': 250 });
    const orders = Array.from({ length: 263 }, (_, i) => `order-${i}`);
    const results = await Promise.allSettled(
      orders.map(id => svc.reserve(id, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    assertRejectedOnlyWith(results, InsufficientStockError);
    const confirmed = fulfilled(results);
    assert.equal(confirmed.length, 250);

    await Promise.all(confirmed.map(r => svc.commit(r.orderId)));
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
    await assertLedger(svc, { 'sneaker-limited': 250 });
  });

  test('commits running alongside new reserves on the same sku lose no updates', async () => {
    const svc = await service({ widget: 200 });
    const first = Array.from({ length: 100 }, (_, i) => `first-${i}`);
    await Promise.all(first.map(id => svc.reserve(id, [{ sku: 'widget', qty: 1 }])));

    const second = Array.from({ length: 150 }, (_, i) => `second-${i}`);
    const results = await Promise.allSettled([
      ...first.map(id => svc.commit(id)),
      ...second.map(id => svc.reserve(id, [{ sku: 'widget', qty: 1 }]))
    ]);
    assertRejectedOnlyWith(results, InsufficientStockError);
    assert.equal(fulfilled(results).length, 200);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 100, reserved: 100, sold: 100 });
  });

  test('restocking during checkout loses neither the new units nor the holds', async () => {
    const svc = await service({ widget: 10 });
    await Promise.all([
      ...Array.from({ length: 10 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
      ...Array.from({ length: 10 }, () => svc.addStock('widget', 1)),
      ...Array.from({ length: 10 }, () => svc.addStock('new-sku', 2))
    ]);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 20, reserved: 10, sold: 0 });
    assert.deepEqual(await svc.snapshot('new-sku'), { sku: 'new-sku', stock: 20, reserved: 0, sold: 0 });
  });

  test('services that share a store do not oversell between them', async () => {
    const store = new JitterStore(90);
    const a = new InventoryService({ store });
    const b = new InventoryService({ store });
    await a.addStock('widget', 10);
    const results = await Promise.allSettled(
      Array.from({ length: 30 }, (_, i) => (i % 2 ? a : b).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
    );
    assertRejectedOnlyWith(results, InsufficientStockError);
    assert.equal(fulfilled(results).length, 10);
    assert.equal(await a.available('widget'), 0);
  });
});

describe('INC-5521: reserved going negative', () => {
  test('release rejects a committed order and leaves its counters alone', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    await svc.commit('o1');
    await assert.rejects(svc.release('o1'), OrderStateError);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  });

  test('expire releases only stale open reservations, not committed or released ones', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('committed', [{ sku: 'widget', qty: 3 }]);
    await svc.reserve('released', [{ sku: 'widget', qty: 2 }]);
    await svc.reserve('stale', [{ sku: 'widget', qty: 1 }]);
    await svc.commit('committed');
    await svc.release('released');
    t = 1000;
    await svc.reserve('fresh', [{ sku: 'widget', qty: 1 }]);
    t = 2000;

    assert.deepEqual(await svc.expire(), ['stale']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 1, sold: 3 });
    assert.deepEqual(await svc.expire(), []);
  });

  test('expire racing with commits never releases an order that committed', async () => {
    let t = 0;
    const svc = await service({ widget: 100 }, { now: () => t, reservationTtlMs: 1000 });
    const orders = Array.from({ length: 30 }, (_, i) => `o${i}`);
    await Promise.all(orders.map(id => svc.reserve(id, [{ sku: 'widget', qty: 2 }])));
    t = 5000;

    const [expired, ...commits] = await Promise.allSettled([svc.expire(), ...orders.map(id => svc.commit(id))]);
    assert.equal(expired.status, 'fulfilled');
    assertRejectedOnlyWith(commits, OrderStateError);
    const committed = fulfilled(commits).map(r => r.orderId);
    assert.deepEqual([...expired.value, ...committed].sort(), [...orders].sort());
    await assertLedger(svc, { widget: 100 });
  });

  test('a concurrent commit and release of one order apply exactly one of them', async () => {
    const svc = await service({ widget: 100 });
    const orders = Array.from({ length: 20 }, (_, i) => `o${i}`);
    await Promise.all(orders.map(id => svc.reserve(id, [{ sku: 'widget', qty: 2 }])));

    const results = await Promise.all(
      orders.map((id, i) =>
        Promise.allSettled(i % 2 ? [svc.commit(id), svc.release(id)] : [svc.release(id), svc.commit(id)])
      )
    );
    for (const pair of results) {
      assert.equal(fulfilled(pair).length, 1);
      assertRejectedOnlyWith(pair, OrderStateError);
    }
    await assertLedger(svc, { widget: 100 });
  });

  test('concurrent releases of one order return its units once', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    const results = await Promise.all([svc.release('o1'), svc.release('o1'), svc.release('o1')]);
    assert.ok(results.every(r => r.status === 'released'));
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  });
});

describe('INC-5521: retried checkout held stock twice', () => {
  test('concurrent retries of one order hold its stock once and return the same reservation', async () => {
    const svc = await service({ widget: 10 });
    const items = [{ sku: 'widget', qty: 2 }];
    const results = await Promise.all(Array.from({ length: 5 }, () => svc.reserve('o1', items)));
    for (const reservation of results) {
      assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items });
    }
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 2, sold: 0 });

    await svc.commit('o1');
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
  });
