describe('INC-5521: rejected bundle left an item held', () => {
  test('a bundle with an out-of-stock item holds none of its items', async () => {
    const svc = await service({ shoe: 5, lace: 1 });
    const err = await svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'lace', qty: 2 }]).catch(e => e);
    assert.ok(err instanceof InsufficientStockError);
    assert.equal(err.sku, 'lace');
    assert.equal(err.requested, 2);
    assert.equal(err.available, 1);
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('lace'), 1);
    await assert.rejects(svc.commit('o1'), UnknownOrderError);
  });

  test('a bundle with an unknown sku holds none of its items', async () => {
    const svc = await service({ shoe: 5 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'nope', qty: 1 }]), UnknownSkuError);
    assert.equal(await svc.available('shoe'), 5);
  });

  test('competing bundles listing their skus in opposite orders neither deadlock nor split', { timeout: 5000 }, async () => {
    const svc = await service({ shoe: 10, lace: 5 });
    const results = await Promise.allSettled(
      Array.from({ length: 20 }, (_, i) =>
        svc.reserve(`o${i}`, i % 2
          ? [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]
          : [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 1 }])
      )
    );
    assertRejectedOnlyWith(results, InsufficientStockError);
    assert.equal(fulfilled(results).length, 5);
    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 10, reserved: 5, sold: 0 });
    assert.deepEqual(await svc.snapshot('lace'), { sku: 'lace', stock: 5, reserved: 5, sold: 0 });
  });
});

describe('INC-5521: sold higher than orders shipped', () => {
  test('concurrent commits of one order sell its units once', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    const results = await Promise.all(Array.from({ length: 5 }, () => svc.commit('o1')));
    assert.ok(results.every(r => r.status === 'committed'));
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  });
});

// Reads of a stalled key wait until the test resumes them.
class StallingStore extends Store {
  constructor() {
    super();
    this.stalls = new Map();
  }

  stall(key) {
    let resume;
    this.stalls.set(key, new Promise(resolve => { resume = resolve; }));
    return () => {
      this.stalls.delete(key);
      resume();
    };
  }

  async get(key) {
    await this.stalls.get(key);
    return super.get(key);
  }
}

describe('INC-5490 constraint: unrelated calls do not wait for each other', () => {
  test('calls on other skus and orders finish while one sku is stalled', { timeout: 5000 }, async () => {
    const store = new StallingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('slow', 5);
    await svc.addStock('fast', 5);
    await svc.reserve('to-release', [{ sku: 'fast', qty: 1 }]);

    const resume = store.stall('sku:slow');
    let slowSettled = false;
    const slow = svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]).finally(() => { slowSettled = true; });

    await svc.reserve('fast-order', [{ sku: 'fast', qty: 1 }]);
    await svc.commit('fast-order');
    await svc.release('to-release');
    await svc.addStock('fast', 1);
    assert.deepEqual(await svc.expire(), []);
    assert.equal(slowSettled, false, 'the stalled call should still be waiting on the store');

    resume();
    assert.equal((await slow).status, 'reserved');
    assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 5, reserved: 0, sold: 1 });
  });
});

describe('store failures', () => {
  test('a failed store write rejects the call and does not leave the sku locked', { timeout: 5000 }, async () => {
    const store = new Store();
    const svc = new InventoryService({ store });
    await svc.addStock('widget', 5);
    const set = store.set.bind(store);
    store.set = async () => {
      store.set = set;
      throw new Error('store unavailable');
    };

    await assert.rejects(svc.reserve('o1', [{ sku: 'widget', qty: 1 }]), /store unavailable/);
    await svc.reserve('o2', [{ sku: 'widget', qty: 2 }]);
    assert.equal(await svc.available('widget'), 3);
  });
});

describe('mixed checkout workload', () => {
  test('40 workers reserving, retrying, committing, releasing, restocking and expiring keep every counter consistent', async () => {
    const rand = random(40);
    let t = 0;
    const skus = ['a', 'b', 'c', 'd', 'e'];
    const received = Object.fromEntries(skus.map(sku => [sku, 30]));
    const svc = await service(received, { now: () => t, reservationTtlMs: 1000 });
    const pick = () => skus[Math.floor(rand() * skus.length)];
    const settled = [];

    const worker = async w => {
      for (let n = 0; n < 10; n++) {
        const orderId = `w${w}-o${n}`;
        const items = [...new Set([pick(), pick(), pick()])].map(sku => ({ sku, qty: 1 + Math.floor(rand() * 3) }));
        const attempts = rand() < 0.3 ? 2 : 1;
        const reserves = await Promise.allSettled(Array.from({ length: attempts }, () => svc.reserve(orderId, items)));
        settled.push(...reserves);
        if (reserves[0].status === 'rejected') continue;

        const action = rand();
        if (action < 0.5) {
          settled.push(...(await Promise.allSettled([svc.commit(orderId), svc.commit(orderId)])));
        } else if (action < 0.8) {
          settled.push(...(await Promise.allSettled([svc.release(orderId), svc.commit(orderId)])));
        }
        // Otherwise the order is abandoned and left for expire().
      }
    };

    const restocker = async () => {
      for (let n = 0; n < 20; n++) {
        const sku = pick();
        await svc.addStock(sku, 1);
        received[sku] += 1;
      }
    };

    const nightlyExpire = async () => {
      for (let turn = 0; turn < 200; turn++) await tick();
      t = 5000;
      return svc.expire();
    };

    const [expired] = await Promise.all([
      nightlyExpire(),
      restocker(),
      ...Array.from({ length: 40 }, (_, w) => worker(w))
    ]);

    assertRejectedOnlyWith(settled, InsufficientStockError, OrderStateError);
    for (const orderId of expired) {
      assert.equal((await svc.store.get(`order:${orderId}`)).status, 'released', `${orderId} was expired`);
    }
    await assertLedger(svc, received);

    t = 10000;
    await svc.expire();
    await assertLedger(svc, received);
    for (const sku of skus) {
      assert.equal((await svc.snapshot(sku)).reserved, 0);
    }
  });
});

