'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/lock');

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

test('callers of one key run one at a time, in arrival order', async () => {
  const lock = new KeyedLock();
  const events = [];
  let active = 0;
  await Promise.all([1, 2, 3].map(n => lock.run(['k'], async () => {
    active += 1;
    assert.equal(active, 1);
    events.push(`start ${n}`);
    await tick();
    await tick();
    events.push(`end ${n}`);
    active -= 1;
  })));
  assert.deepEqual(events, ['start 1', 'end 1', 'start 2', 'end 2', 'start 3', 'end 3']);
});

test('callers with no key in common do not wait for each other', { timeout: 2000 }, async () => {
  const lock = new KeyedLock();
  let finish;
  const holder = lock.run(['a'], () => new Promise(resolve => { finish = resolve; }));
  assert.equal(await lock.run(['b'], async () => 'done'), 'done');
  finish();
  await holder;
});

test('overlapping key sets listed in opposite orders do not deadlock', { timeout: 2000 }, async () => {
  const lock = new KeyedLock();
  const done = [];
  await Promise.all([
    lock.run(['a', 'b'], async () => { await tick(); done.push('ab'); }),
    lock.run(['b', 'a'], async () => { await tick(); done.push('ba'); })
  ]);
  assert.deepEqual(done.sort(), ['ab', 'ba']);
});

test('a key listed twice in one call is taken once', { timeout: 2000 }, async () => {
  const lock = new KeyedLock();
  assert.equal(await lock.run(['k', 'k'], async () => 'ok'), 'ok');
});

test('a rejected callback passes its error through and frees its keys', { timeout: 2000 }, async () => {
  const lock = new KeyedLock();
  const waiting = lock.run(['k'], async () => 'next');
  await assert.rejects(lock.run(['k'], async () => { throw new Error('boom'); }), /boom/);
  assert.equal(await waiting, 'next');
  assert.equal(await lock.run(['k'], async () => 'after'), 'after');
});

test('a key is forgotten once nobody holds or waits for it', async () => {
  const lock = new KeyedLock();
  await Promise.all([lock.run(['a', 'b'], tick), lock.run(['b'], tick), lock.run(['c'], tick)]);
  assert.equal(lock.waiters.size, 0);
});

