'use strict';

// Reproductions for INC-5521. Each describe block maps to one symptom in
// ISSUE.md. The store yields to the event loop on every call, so firing calls
// together with Promise.all interleaves them the way 40 checkout workers do.

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

// mulberry32: a seeded PRNG so a failing interleaving can be replayed.
function random(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

// Adds 0-3 extra event-loop turns before each call, so concurrent operations
// interleave in more orders than the fixed one-turn Store produces.
class JitterStore extends Store {
  constructor(seed) {
    super();
    this.rand = random(seed);
  }

  async jitter() {
    for (let turns = Math.floor(this.rand() * 4); turns > 0; turns--) {
      await tick();
    }
  }

  async get(key) {
    await this.jitter();
    return super.get(key);
  }

  async set(key, value) {
    await this.jitter();
    return super.set(key, value);
  }

  async keys(prefix) {
    await this.jitter();
    return super.keys(prefix);
  }
}

async function service(stock, options = {}) {
  const svc = new InventoryService({ store: new JitterStore(5521), ...options });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function fulfilled(results) {
  return results.filter(r => r.status === 'fulfilled').map(r => r.value);
}

function assertRejectedOnlyWith(results, ...errorTypes) {
  for (const r of results) {
    if (r.status === 'rejected') {
      assert.ok(
        errorTypes.some(type => r.reason instanceof type),
        `unexpected rejection: ${r.reason && r.reason.stack}`
      );
    }
  }
}

// Recomputes each SKU's counters from the order records and checks they match
// the SKU record: reserved is what open orders hold, sold is what committed
// orders took, and available never goes negative.
async function assertLedger(svc, received) {
  const orders = await Promise.all((await svc.store.keys('order:')).map(key => svc.store.get(key)));
  for (const [sku, stock] of Object.entries(received)) {
    let reserved = 0;
    let sold = 0;
    for (const order of orders) {
      for (const line of order.items) {
        if (line.sku !== sku) continue;
        if (order.status === 'reserved') reserved += line.qty;
        if (order.status === 'committed') sold += line.qty;
      }
    }
    assert.deepEqual(await svc.snapshot(sku), { sku, stock: stock - sold, reserved, sold }, `ledger for ${sku}`);
    assert.ok(stock - sold - reserved >= 0, `available for ${sku} went negative`);
  }
}

describe('INC-5521: oversold stock', () => {
  test('263 concurrent orders for 250 units confirm exactly 250', async () => {
    const svc = await service({ 'sneaker-limited': 250 });
    const orders = Array.from({ length: 263 }, (_, i) => `order-${i}`);
    const results = await Promise.allSettled(
      orders.map(id => svc.reserve(id, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    assertRejectedOnlyWith(results, InsufficientStockError);
    const confirmed = fulfilled(results);
    assert.equal(confirmed.length, 250);

    await Promise.all(confirmed.map(r => svc.commit(r.orderId)));
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
    await assertLedger(svc, { 'sneaker-limited': 250 });
  });

  test('commits running alongside new reserves on the same sku lose no updates', async () => {
    const svc = await service({ widget: 200 });
    const first = Array.from({ length: 100 }, (_, i) => `first-${i}`);
    await Promise.all(first.map(id => svc.reserve(id, [{ sku: 'widget', qty: 1 }])));

    const second = Array.from({ length: 150 }, (_, i) => `second-${i}`);
    const results = await Promise.allSettled([
      ...first.map(id => svc.commit(id)),
      ...second.map(id => svc.reserve(id, [{ sku: 'widget', qty: 1 }]))
    ]);
    assertRejectedOnlyWith(results, InsufficientStockError);
    assert.equal(fulfilled(results).length, 200);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 100, reserved: 100, sold: 100 });
  });

  test('restocking during checkout loses neither the new units nor the holds', async () => {
    const svc = await service({ widget: 10 });
    await Promise.all([
      ...Array.from({ length: 10 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
      ...Array.from({ length: 10 }, () => svc.addStock('widget', 1)),
      ...Array.from({ length: 10 }, () => svc.addStock('new-sku', 2))
    ]);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 20, reserved: 10, sold: 0 });
    assert.deepEqual(await svc.snapshot('new-sku'), { sku: 'new-sku', stock: 20, reserved: 0, sold: 0 });
  });

  test('services that share a store do not oversell between them', async () => {
    const store = new JitterStore(90);
    const a = new InventoryService({ store });
    const b = new InventoryService({ store });
    await a.addStock('widget', 10);
    const results = await Promise.allSettled(
      Array.from({ length: 30 }, (_, i) => (i % 2 ? a : b).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
    );
