describe('INC-5521: reserved going negative', () => {
  test('release rejects a committed order and leaves its counters alone', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    await svc.commit('o1');
    await assert.rejects(svc.release('o1'), OrderStateError);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  });

  test('expire releases only stale open reservations, not committed or released ones', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('committed', [{ sku: 'widget', qty: 3 }]);
    await svc.reserve('released', [{ sku: 'widget', qty: 2 }]);
    await svc.reserve('stale', [{ sku: 'widget', qty: 1 }]);
    await svc.commit('committed');
    await svc.release('released');
    t = 1000;
    await svc.reserve('fresh', [{ sku: 'widget', qty: 1 }]);
    t = 2000;

    assert.deepEqual(await svc.expire(), ['stale']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 1, sold: 3 });
    assert.deepEqual(await svc.expire(), []);
  });

  test('expire racing with commits never releases an order that committed', async () => {
    let t = 0;
    const svc = await service({ widget: 100 }, { now: () => t, reservationTtlMs: 1000 });
    const orders = Array.from({ length: 30 }, (_, i) => `o${i}`);
    await Promise.all(orders.map(id => svc.reserve(id, [{ sku: 'widget', qty: 2 }])));
    t = 5000;

    const [expired, ...commits] = await Promise.allSettled([svc.expire(), ...orders.map(id => svc.commit(id))]);
    assert.equal(expired.status, 'fulfilled');
    assertRejectedOnlyWith(commits, OrderStateError);
    const committed = fulfilled(commits).map(r => r.orderId);
    assert.deepEqual([...expired.value, ...committed].sort(), [...orders].sort());
    await assertLedger(svc, { widget: 100 });
  });

  test('a concurrent commit and release of one order apply exactly one of them', async () => {
    const svc = await service({ widget: 100 });
    const orders = Array.from({ length: 20 }, (_, i) => `o${i}`);
    await Promise.all(orders.map(id => svc.reserve(id, [{ sku: 'widget', qty: 2 }])));

    const results = await Promise.all(
      orders.map((id, i) =>
        Promise.allSettled(i % 2 ? [svc.commit(id), svc.release(id)] : [svc.release(id), svc.commit(id)])
      )
    );
    for (const pair of results) {
      assert.equal(fulfilled(pair).length, 1);
      assertRejectedOnlyWith(pair, OrderStateError);
    }
    await assertLedger(svc, { widget: 100 });
  });

  test('concurrent releases of one order return its units once', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    const results = await Promise.all([svc.release('o1'), svc.release('o1'), svc.release('o1')]);
    assert.ok(results.every(r => r.status === 'released'));
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  });
});

