1	'use strict';
2	
3	const { Store } = require('./store');
4	const { KeyedLock } = require('./lock');
5	const {
6	  ValidationError,
7	  UnknownSkuError,
8	  UnknownOrderError,
9	  InsufficientStockError,
10	  OrderStateError
11	} = require('./errors');
12	
13	const DEFAULT_TTL_MS = 15 * 60 * 1000;
14	const ORDER_PREFIX = 'order:';
15	
16	// The locks guard store keys, so services built on the same store share them.
17	const storeLocks = new WeakMap();
18	
19	function locksFor(store) {
20	  let locks = storeLocks.get(store);
21	  if (!locks) {
22	    locks = new KeyedLock();
23	    storeLocks.set(store, locks);
24	  }
25	  return locks;
26	}
27	
28	/**
29	 * Stock reservations for checkout.
30	 *
31	 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
32	 * held for orders that have not been committed) and `sold`. Available stock
33	 * is `stock - reserved` and must never go below zero.
34	 *
35	 * An order moves reserved -> committed, or reserved -> released. Committing
36	 * turns its held units into sold units; releasing returns them.
37	 *
38	 * The service is called concurrently by every checkout worker. The store only
39	 * offers get and set, so each read-modify-write runs under a lock on the keys
40	 * it touches: the order first, then its SKUs in sorted order. Calls that share
41	 * no SKU and no order never wait for each other.
42	 */
43	class InventoryService {
44	  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
45	    this.store = store;
46	    this.ttl = reservationTtlMs;
47	    this.now = now;
48	    this.locks = locksFor(store);
49	  }
50	
51	  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
52	  async addStock(sku, qty) {
53	    assertSku(sku);
54	    assertQty(qty);
55	    return this.withSkus([sku], async () => {
56	      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
57	      item.stock += qty;
58	      await this.store.set(skuKey(sku), item);
59	      return { sku, ...item };
60	    });
61	  }
62	
63	  /** Units that can still be reserved. */
64	  async available(sku) {
65	    const item = await this.getItem(sku);
66	    return item.stock - item.reserved;
67	  }
68	
69	  /** The SKU's counters. */
70	  async snapshot(sku) {
71	    const item = await this.getItem(sku);
72	    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
73	  }
74	
75	  /**
76	   * Hold stock for an order: all of its items, or none of them.
77	   *
78	   * Idempotent by orderId: checkout retries a timed-out request with the same
79	   * orderId, and a retry must return the existing reservation rather than
80	   * hold the stock twice.
81	   *
82	   * Rejects with InsufficientStockError when any item cannot be held, and
83	   * then holds nothing.
84	   */
85	  async reserve(orderId, items) {
86	    assertOrderId(orderId);
87	    assertItems(items);
88	    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
89	    return this.withOrder(orderId, async () => {
90	      const existing = await this.store.get(orderKey(orderId));
91	      if (existing) {
92	        return toReservation(existing);
93	      }
94	      await this.withSkus(lines.map(({ sku }) => sku), async () => {
95	        // Check every line before writing any, so a short or unknown SKU
96	        // leaves the others untouched.
97	        const held = [];
98	        for (const { sku, qty } of lines) {
99	          const item = await this.getItem(sku);
100	          const free = item.stock - item.reserved;
101	          if (free < qty) {
102	            throw new InsufficientStockError(sku, qty, free);
103	          }
104	          held.push({ sku, item: { ...item, reserved: item.reserved + qty } });
105	        }
106	        for (const { sku, item } of held) {
107	          await this.store.set(skuKey(sku), item);
108	        }
109	      });
110	      const order = { orderId, items: lines, status: 'reserved', createdAt: this.now() };
111	      await this.store.set(orderKey(orderId), order);
112	      return toReservation(order);
113	    });
114	  }
115	
116	  /**
117	   * Turn a reservation into a sale. Idempotent: committing a committed order
118	   * returns it unchanged. A released order cannot be committed.
119	   */
120	  async commit(orderId) {
121	    assertOrderId(orderId);
122	    return this.withOrder(orderId, async () => {
123	      const order = await this.getOrder(orderId);
124	      if (order.status === 'committed') {
125	        return toReservation(order);
126	      }
127	      if (order.status !== 'reserved') {
128	        throw new OrderStateError(orderId, order.status, 'commit');
129	      }
130	      await this.closeOrder(order, 'committed');
131	      return toReservation(order);
132	    });
133	  }
134	
135	  /**
136	   * Cancel a reservation and return its units. Idempotent: releasing a
137	   * released order returns it unchanged. A committed order cannot be
138	   * released; its units have been sold.
139	   */
140	  async release(orderId) {
141	    assertOrderId(orderId);
142	    return this.withOrder(orderId, async () => {
143	      const order = await this.getOrder(orderId);
144	      if (order.status === 'released') {
