cat >> tests/inventory.test.js <<'EOF'

test('expire only releases reservations strictly older than the TTL', async () => {
  let t = 0;
  const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
  await svc.addStock('widget', 5);
  await svc.reserve('old', [{ sku: 'widget', qty: 1 }]);
  t = 1;
  await svc.reserve('at-ttl', [{ sku: 'widget', qty: 1 }]);
  t = 1001;
  assert.deepEqual(await svc.expire(), ['old']);
  assert.equal(await svc.available('widget'), 4);
});

test('a TTL that is not a number expires nothing', async () => {
  const svc = new InventoryService({ reservationTtlMs: NaN });
  await svc.addStock('widget', 5);
  await svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
  assert.deepEqual(await svc.expire(), []);
  assert.equal(await svc.available('widget'), 4);
});

test('the public surface is unchanged', () => {
  assert.deepEqual(Object.getOwnPropertyNames(InventoryService.prototype).sort(), [
    'addStock', 'available', 'commit', 'constructor', 'expire', 'getItem', 'getOrder', 'release', 'reserve', 'snapshot'
  ]);
  assert.deepEqual(Object.keys(new InventoryService()).sort(), ['now', 'store', 'ttl']);
});
EOF
